public enum ContentAvailability { Unknown, Listed, Unavailable }
public enum ContentAdvisory { Unknown, Clean, Explicit }

public sealed record CatalogItem(
    [property: JsonRequired] string Id,
    [property: JsonRequired] string Title,
    [property: JsonRequired] string Creator,
    [property: JsonRequired] ContentKind Kind,
    [property: JsonRequired] string Description,
    Uri? ExternalUrl = null,
    string? CreatorId = null,
    DateOnly? ReleaseDate = null,
    string? Edition = null,
    int? DurationSeconds = null,
    ContentAvailability Availability = ContentAvailability.Unknown,
    ContentAdvisory Advisory = ContentAdvisory.Unknown);

public static CatalogSnapshot LoadBundled()
{
    using var items = OpenResource("catalog.json");
    using var creators = OpenResource("creators.json");
    return Load(items, creators);
}

public async Task UpdateAsync(
    string? text, Action<string> apply, Action reportError)
{
    ArgumentNullException.ThrowIfNull(apply);
    ArgumentNullException.ThrowIfNull(reportError);
    var current = ++revision;
    active?.Cancel();
    using var own = new CancellationTokenSource();
    active = own;
    try
    {
        // Clearing is immediate and still invalidates older pending input.
        if (!string.IsNullOrEmpty(text))
            await delay(interval, own.Token);
        if (!own.IsCancellationRequested && current == revision)
            apply(text ?? "");
    }
    catch (OperationCanceledException) when (own.IsCancellationRequested) { }
    catch (Exception)
    {
        if (!own.IsCancellationRequested && current == revision) reportError();
    }
    finally
    {
        if (ReferenceEquals(active, own)) active = null;
    }
}

public void Toggle(string id)
{
    if (!IsLoaded) throw new
        InvalidOperationException("Load favorites before editing.");
    FavoriteIdCodec.Validate([id]);
    var next = new HashSet<string>(ids, StringComparer.Ordinal);
    if (!next.Remove(id)) next.Add(id);
    var ordered = FavoriteIdCodec.Validate(next);
    store.Save(ordered);
    ids = new HashSet<string>(ordered, StringComparer.Ordinal);
}

private async Task OpenAsync()
{
    var own = revision;
    var url = Item!.ExternalUrl!;
    LinkMessage = ""; Notify(nameof(LinkMessage));
    string result;
    try { result = await browser!.OpenAsync(url) ? UiText.BrowserHandedOff :
        UiText.LinkFailed; }
    catch (OperationCanceledException) { result = UiText.LinkCanceled; }
    catch (Exception) { result = UiText.LinkFailed; }
    if (own != revision) return;
    LinkMessage = result; Notify(nameof(LinkMessage));
}

public void Edit(SongRequest value)
{
    Draft = value; Review = null; IsDirty = true;
    Status = "Unsaved changes."; Errors = ""; Changed();
}
public bool Next()
{
    var errors = SongRequestRules.Validate(Draft, Step);
    Errors = string.Join("\n", errors.Select(e => e.Message));
    if (errors.Count != 0) { Changed(); return false; }
    if (Step < 2) Step++;
    else Review = Draft.ForReview();
    Changed(); return true;
}

private void Field(string label, string value, int limit,
    Action<string> update, bool multiline = false, bool email = false)
{
    panel.Children.Add(new Label { Text = label });
    InputView input = multiline
        ? new Editor { AutoSize = EditorAutoSizeOption.TextChanges,
            MinimumHeightRequest = 120 }
        : new Entry { Keyboard = email ? Keyboard.Email : Keyboard.Default };
    input.MaxLength = limit; input.Text = value;
    SemanticProperties.SetHint(input, label);
    input.TextChanged += (_, args) => update(args.NewTextValue ?? "");
    panel.Children.Add(input);
}

public bool Save()
{
    try
    {
        store.Save(Draft); IsDirty = false;
        Status = "Draft saved on this device."; Changed(); return true;
    }
    catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
    {
        Status = "Could not save. Your edits are still open; try again.";
        Changed(); return false;
    }
}

namespace GnazzosWorld.Core.Orders;

// Snapshot of the uploaded website, not a live price or checkout contract.
public static class SongPricing
{
    public const string Version = "website-snapshot-2026-11-14";

    public static decimal Calculate(int minutes, bool withVoice, int quantity)
    {
        if (quantity is < 1 or > 3)
            throw new ArgumentOutOfRangeException(nameof(quantity));
        decimal unit = (minutes, withVoice) switch
        {
            (1, false) => 49m, (1, true) => 79m,
            (2, false) => 79m, (2, true) => 129m,
            (3, false) => 109m, (3, true) => 179m,
            (4, false) => 139m, (4, true) => 229m,
            (6, false) => 199m, (6, true) => 319m,
            (8, false) => 259m, (8, true) => 399m,
            _ => throw new ArgumentOutOfRangeException(nameof(minutes))
        };
        // All songs have the same length/style; discounts apply per song.
        decimal factor = quantity switch { 1 => 1m, 2 => 1.9m, _ => 2.7m };
        return decimal.Round(unit * factor, 2, MidpointRounding.AwayFromZero);
    }
}

